{"policy":"permit (
    principal is Person,
    action == Action::"viewMedicalRecord",
    resource is MedicalRecord
)
when {
    principal.roles.contains(Role::"attendingPhysician") &&
    (!resource.isSealed || principal.clearedLevel >= resource.sensitivity)
};

forbid (
    principal is Person,
    action == Action::"viewMedicalRecord",
    resource is MedicalRecord
)
when {
    (principal.roles.contains(Role::"attendingPhysician") ||
     principal.roles.contains(Role::"resident") ||
     principal.roles.contains(Role::"nurse")) &&
    resource.isSealed &&
    principal.clearedLevel < resource.sensitivity
};"}
